{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f2ea;--accent:#7a4f3a;--muted:#857064;--card:#fff;--green:#7aa66b}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#2b2b2b;background:linear-gradient(180deg,rgba(122,79,58,0.04),transparent),var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;position:sticky;top:0;background:rgba(247,242,234,0.85);backdrop-filter:blur(6px);border-bottom:1px solid rgba(122,79,58,0.06)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#c28b66);display:flex;align-items:center;justify-content:center;color:white;font-weight:700;box-shadow:0 6px 18px rgba(122,79,58,0.08)}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    nav a:hover{color:var(--accent)}
    main{max-width:980px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center;padding:28px;border-radius:12px;background:linear-gradient(180deg,rgba(122,79,58,0.03),transparent);box-shadow:inset 0 -1px 0 rgba(122,79,58,0.02)}
    .eyebrow{color:var(--accent);font-weight:700}
    h1{margin:0;font-size:28px}
    p.lead{color:var(--muted);margin:6px 0 0}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(43,43,43,0.06);border:1px solid rgba(0,0,0,0.03)}
    .card h3{margin:0 0 8px;color:var(--accent)}
    .muted{color:var(--muted);font-size:14px}
    .inv{font-weight:700;color:var(--green);margin-top:10px}
    .cta-row{display:flex;gap:10px;align-items:center;margin-top:18px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:none;cursor:pointer;font-weight:700}
    .btn.secondary{background:transparent;border:1px solid rgba(122,79,58,0.12);color:var(--accent)}
    .small{font-size:13px;color:var(--muted)}
    footer{max-width:980px;margin:36px auto;padding:18px 20px;color:var(--muted)}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.revealed{opacity:1;transform:none}
    /* breathing circle */
    .breath-svg{width:120px;height:120px}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(16,12,8,0.45);display:none;align-items:center;justify-content:center;padding:20px;z-index:60}
    .modal{max-width:720px;width:100%;background:var(--card);padding:20px;border-radius:12px}
    .modal h2{margin:0 0 8px}
    .steps{display:flex;gap:8px;flex-direction:column}
    .hidden{display:none}
    @media(prefers-reduced-motion:reduce){
      .reveal{transition:none;transform:none;opacity:1}
      .breath-circle{animation:none}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div class="small">A practical, soulful path for changing rhythms</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="approach.html">Our Way</a>
      <a href="services.html" style="color:var(--accent)">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Who We Are</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" aria-labelledby="hero-title">
      <div class="eyebrow">Offerings — tailored intensives</div>
      <h1 id="hero-title">Intentional programs for turning a stuck season into steady practices</h1>
      <p class="lead">Short, concentrated work designed to reorient energy and habits — grounded in lifestyle, nutrition, and somatic practice. Choose a focused pathway or combine modules over time.</p>
      <div class="cta-row">
        <button class="btn" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
        <button class="btn secondary" id="try-btn">Try it now — guided exercise</button>
        <div class="small">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </div>
    </section>

    <section class="grid" aria-label="Programs">
      <article class="card reveal">
        <h3>Deep Spring Intensive — 6 weeks</h3>
        <div class="muted">An immersive pathway: intake, focused weekly sessions, personalized plan.</div>
        <ul style="margin-top:10px;color:var(--muted)">
          <li>Comprehensive lifestyle review</li>
          <li>Therapeutic, evidence-informed nutrition strategies</li>
          <li>Somatic practices to anchor routine</li>
        </ul>
        <div class="inv">Investment: starting at $2,250 — payment plans available</div>
        <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Begin an Intensive</button></div>
      </article>

      <article class="card reveal">
        <h3>Rhythm Reset Day — single session</h3>
        <div class="muted">A concentrated day to identify friction points and leave with clear first steps.</div>
        <div class="inv">Investment: $395</div>
        <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Schedule a Reset</button></div>
      </article>

      <article class="card reveal">
        <h3>Nurture Series — 3-month support</h3>
        <div class="muted">Weekly touchpoints, targeted lessons, and a community check-in month.</div>
        <div class="inv">Investment: $1,150 — subscription-friendly</div>
        <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Join the Series</button></div>
      </article>
    </section>

    <section class="card" style="margin-top:20px" aria-labelledby="why-title">
      <h2 id="why-title">How these work — a short map</h2>
      <p class="muted">We combine an initial discovery, a focused phase of adjustment (addressing sleep, food, movement, stress patterns), and practical anchors you can keep using after the program ends.</p>
      <ol style="color:var(--muted)">
        <li>Assess patterns and priorities</li>
        <li>Shift small, measurable habits</li>
        <li>Embed routines so gains hold</li>
      </ol>
    </section>

    <section class="card reveal" style="margin-top:18px">
      <h2>What people notice</h2>
      <blockquote style="margin:0;color:var(--muted)">"Better evenings, clearer energy windows, and fewer moments of being overwhelmed" — a recent participant</blockquote>
      <p class="small" style="margin-top:8px;color:var(--muted)">We emphasize learning and sustainable changes — not quick fixes.</p>
    </section>

    <section class="card reveal" style="margin-top:18px">
      <h2>Questions</h2>
      <details>
        <summary>How do I choose between the Intensive and the Series?</summary>
        <p class="muted">If you want a concentrated reset with clear timelines, pick the Intensive. If you prefer gradual guidance with ongoing touchpoints, the Series is for you.</p>
      </details>
      <details style="margin-top:6px">
        <summary>Are these covered by insurance?</summary>
        <p class="muted">Coverage varies. We provide detailed invoices you can submit to insurers where appropriate.</p>
      </details>
    </section>

  </main>

  <footer>
    <div class="small">Questions? Reach us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> — Serving {{CITY}}, {{STATE}}</div>
  </footer>

  <!-- Guided exercise modal -->
  <div class="modal-backdrop" id="modal-backdrop" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <h2 id="modal-title">Try it now — a brief guided practice</h2>
      <p class="muted">Choose a short practice below. This is an experiential tool, not medical advice.</p>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn" id="btn-breath">Breathing (2 min)</button>
        <button class="btn secondary" id="btn-journal">Journaling prompt</button>
        <button class="btn secondary" id="btn-intent">Set a small intention</button>
        <button style="margin-left:auto" class="btn secondary" id="close-modal">Close</button>
      </div>

      <div id="exercise-area" style="margin-top:14px">
        <div id="breath-area" class="hidden">
          <svg class="breath-svg" viewBox="0 0 120 120" aria-hidden="true">
            <circle cx="60" cy="60" r="36" fill="none" stroke="#E6E0D8" stroke-width="10"></circle>
            <circle id="breath-circle" cx="60" cy="60" r="36" fill="none" stroke="#7aa66b" stroke-width="10" stroke-linecap="round" transform="rotate(-90 60 60)"></circle>
          </svg>
          <div style="color:var(--muted)"><strong id="breath-instr">Prepare to breathe.</strong></div>
        </div>
        <div id="journal-area" class="hidden">
          <div class="muted">Prompt: Name three small things that gave you an ease today. Write one sentence for each.</div>
          <textarea id="journal-text" rows="5" style="width:100%;margin-top:10px;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)"></textarea>
          <div style="margin-top:8px"><button class="btn" id="save-journal">Save (local)</button></div>
        </div>
        <div id="intent-area" class="hidden">
          <div class="muted">Pick one small, doable intention for the rest of the day.</div>
          <input id="intent-input" placeholder="Example: Stand and stretch at 11:00" style="width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:8px">
          <div style="margin-top:8px"><button class="btn" id="save-intent">Save intention</button></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('.reveal');
      if(reduce){
        reveals.forEach(function(el){el.classList.add('revealed')});
        return;
      }
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if(entry.isIntersecting){
            entry.target.classList.add('revealed');
            obs.unobserve(entry.target);
          }
        })
      },{threshold:0.12});
      reveals.forEach(function(el){obs.observe(el)});
    })();

    // Modal and guided exercise logic
    (function(){
      var backdrop = document.getElementById('modal-backdrop');
      var tryBtn = document.getElementById('try-btn');
      var closeBtn = document.getElementById('close-modal');
      var breathBtn = document.getElementById('btn-breath');
      var journalBtn = document.getElementById('btn-journal');
      var intentBtn = document.getElementById('btn-intent');
      var breathArea = document.getElementById('breath-area');
      var journalArea = document.getElementById('journal-area');
      var intentArea = document.getElementById('intent-area');
      var breathInstr = document.getElementById('breath-instr');
      var breathCircle = document.getElementById('breath-circle');

      function showModal(){backdrop.style.display='flex';backdrop.setAttribute('aria-hidden','false')}
      function hideModal(){backdrop.style.display='none';backdrop.setAttribute('aria-hidden','true');stopBreath()}

      tryBtn.addEventListener('click', showModal);
      closeBtn.addEventListener('click', hideModal);

      // breathing exercise
      var breathTimer;
      function stopBreath(){
        clearInterval(breathTimer);
        breathCircle.style.strokeDasharray='0 226';
        breathInstr.textContent='Prepare to breathe.';
      }

      breathBtn.addEventListener('click', function(){
        journalArea.classList.add('hidden');intentArea.classList.add('hidden');breathArea.classList.remove('hidden');
        startBreath();
      });

      function startBreath(){
        var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if(reduce){
          breathInstr.textContent='Take three slow breaths at your own pace.';return;
        }
        var phases = [ {label:'Breathe in',ms:4000}, {label:'Hold',ms:2000}, {label:'Breathe out',ms:6000} ];
        var idx=0;var total=120000; // 2 minutes
        breathInstr.textContent=phases[idx].label;
        // prepare stroke
        var circumference = 2 * Math.PI * 36;
        breathCircle.style.strokeDasharray = '0 ' + circumference;
        breathTimer = setInterval(function(){
          var phase = phases[idx];
          breathInstr.textContent = phase.label;
          // animate stroke for phase length
          var start = Date.now();
          var dur = phase.ms;
          var frame = setInterval(function(){
            var t = (Date.now()-start)/dur; if(t>1) t=1;
            var len = Math.round(circumference * t);
            if(phase.label==='Breathe out'){
              breathCircle.style.strokeDasharray = (circumference - len) + ' ' + circumference;
            } else {
              breathCircle.style.strokeDasharray = len + ' ' + circumference;
            }
            if(t>=1) clearInterval(frame);
          },30);
          idx = (idx+1) % phases.length;
        }, phases[idx].ms);
        // stop after 2 minutes
        setTimeout(function(){stopBreath(); breathInstr.textContent='Finished. Notice how you feel.'}, total);
      }

      // journaling
      document.getElementById('save-journal').addEventListener('click', function(){
        var txt = document.getElementById('journal-text').value;
        if(!txt.trim()){alert('Write a sentence or two.');return}
        try{localStorage.setItem('journal-sample',txt);alert('Saved to local storage.') }catch(e){alert('Unable to save.')}
      });

      journalBtn.addEventListener('click', function(){
        breathArea.classList.add('hidden');intentArea.classList.add('hidden');journalArea.classList.remove('hidden');
      });

      intentBtn.addEventListener('click', function(){
        breathArea.classList.add('hidden');journalArea.classList.add('hidden');intentArea.classList.remove('hidden');
      });

      document.getElementById('save-intent').addEventListener('click', function(){
        var v = document.getElementById('intent-input').value;
        if(!v.trim()){alert('Type a small intention.');return}
        try{localStorage.setItem('today-intent',v);alert('Intent saved.') }catch(e){alert('Unable to save.')}
      });

    })();
  </script>
</body>
</html>"} 
