  <title>Our Way — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f6f1;--accent:#6b4a36;--muted:#665a50;--card:#fff;--accent-2:#b07a57}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#2d2d2d;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;background:linear-gradient(180deg,rgba(176,122,87,0.04),transparent);position:sticky;top:0;border-bottom:1px solid rgba(0,0,0,0.04)}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
